java.io.File tempFile = outputPath.resolve("test_overwrite.png").toFile();
try (java.io.FileOutputStream fos = new java.io.FileOutputStream(tempFile)) {
    fos.write(new byte[]{1, 2, 3, 4, 5});
}
long initialSize = tempFile.length();

boolean threwException = false;
try {
    net.coobird.thumbnailator.Thumbnails.of(sourceImage)
        .size(10, 10)
        .allowOverwrite(false)
        .toFile(tempFile);
} catch (Exception e) {
    threwException = true;
}

long sizeAfterFalse = tempFile.length();
assert sizeAfterFalse == initialSize : "File should not be overwritten when allowOverwrite is false";

net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(10, 10)
    .allowOverwrite(true)
    .toFile(tempFile);

long sizeAfterTrue = tempFile.length();
assert sizeAfterTrue > initialSize : "File should be overwritten when allowOverwrite is true";

System.out.println("__CHECK__ allowOverwrite " + threwException + "_" + sizeAfterTrue);
